/* Finite State Machine (FSM) for Alarm System */
states {
    Idle;
    MediumAlarm;
    HighAlarm;
    Paused;
}

initial state is Idle;

transitions {
    Idle --> MediumAlarm : AlarmMediumTriggered;
    MediumAlarm --> Idle : AlarmMediumResolved;
    Idle --> HighAlarm : AlarmHighTriggered;
    HighAlarm --> Idle : AlarmHighResolved;
    Idle --> Paused : AudioPausePressed;
    Paused --> Idle : PauseTimeout;
}

events {
    AlarmMediumTriggered;
    AlarmMediumResolved;
    AlarmHighTriggered;
    AlarmHighResolved;
    AudioPausePressed;
    PauseTimeout;
}

guards {
    /* Guard for MediumAlarm trigger */
    AlarmMediumTriggered: /* condition from requirement RW-SW-80 */
        apneaTimeExceeded;

    /* Guard for HighAlarm trigger */
    AlarmHighTriggered: /* condition from requirement RW-SW-82 */
        breathRateExceeded;

    /* Guard for pause initiation */
    AudioPausePressed: true;

    /* Guard for pause timeout */
    PauseTimeout: timeElapsed(60s);
}

/* Additional details for guards based on requirements */
guard apneaTimeExceeded {
    /* Requirement RW-SW-80 */
    return !breathDetectedWithin(apneaInterval);
}

guard breathRateExceeded {
    /* Requirement RW-SW-82 */
    return breathRate > breathRateSetting;
}

/* Note: Specific timing and signal details (e.g., flashing frequency, auditory pulses) are assumed to be handled within the respective state logic as per requirements RW-SW-75, RW-SW-76, RW-SW-77, RW-SW-78, RW-SW-83, RW-SW-84. */
